export const Events = {
  /** Progress of a long-running action; ref_id is the action id. */
  ACTION_PROGRESS: "action:progress",
  /** Preferences changed (from any client). */
  PREFERENCES_UPDATED: "preferences:updated",
  /** Agent provider discovery or connection state changed. */
  AGENT_STATUS_CHANGED: "agent:status_changed",
  /** Streamed text, thought, tool call, or completion update from the active agent turn. */
  AGENT_CHAT_EVENT: "agent:chat_event",
  /** A running agent sign-in needs the user: a page to open, a one-time code or a code to paste back. */
  AGENT_LOGIN_PROMPT: "agent:login_prompt",
  /** Pending agent approval queue changed. */
  AGENT_APPROVALS: "agent:approvals",
  /** Shared agent skills or subagents changed. */
  AGENT_CUSTOMIZATIONS_CHANGED: "agent:customizations_changed",
  /** Provider credentials or custom providers changed. */
  PROVIDERS_CHANGED: "providers:changed",
} as const;
export type EventName = (typeof Events)[keyof typeof Events];

export interface EventMap {
  "action:progress": ActionProgress;
  "preferences:updated": Preferences;
  "agent:status_changed": AgentProviderInfo;
  "agent:chat_event": AgentChatEvent;
  "agent:login_prompt": AgentLoginPrompt;
  "agent:approvals": AgentApprovalListResult;
  "agent:customizations_changed": AgentCustomizationsResult;
  "providers:changed": ProvidersListResult;
}

export const NativeEvents = {
  /** Core is ready; call GetConnectionInfo. */
  APP_READY: "app:ready",
  /** Core failed to start; the UI must show a fatal screen. */
  APP_FATAL: "app:fatal",
} as const;
export type NativeEventName = (typeof NativeEvents)[keyof typeof NativeEvents];

export interface NativeEventMap {
  "app:ready": Empty;
  "app:fatal": ErrorBody;
}

/** Methods bound by the desktop shell (window.go.desktop.Bridge). */
export interface BridgeApi {
  /** Waits for the core and returns how to connect. */
  GetConnectionInfo(): Promise<ConnectionInfo>;
  /** Returns build metadata. */
  GetBuildInfo(): Promise<BuildInfo>;
  /** Client mode: stores the remote token in the OS credential store. */
  SetRemoteToken(arg1: string): Promise<void>;
  /** Opens a native file picker to select an executable file. */
  BrowseExecutable(arg1: string): Promise<string>;
  /** Opens a native file picker to select an image file. */
  BrowseImage(arg1: string): Promise<string>;
  /** Opens a native file picker to select multiple image files. */
  BrowseImages(arg1: string): Promise<string[]>;
  /** Opens a native directory picker to select a folder. */
  BrowseDirectory(arg1: string): Promise<string>;
}
